"use client";
// src/textarea.tsx
import {
  textarea as textareaPrimitive
} from "@ui-sdk/core/input";
import { controlRender, useFieldControl } from "./field-context.js";
import { controlProps, elementProps } from "./text-control.js";
import { usePart, usePrimitive } from "./use-primitive.js";
import { createInputController } from "@ui-sdk/core/input";
function Textarea({
  value,
  defaultValue,
  onValueChange,
  controller,
  debug,
  autoResize,
  onSubmit,
  submitShortcut,
  render,
  ...props
}) {
  const field = useFieldControl();
  const textarea = usePrimitive(textareaPrimitive, {
    value,
    defaultValue,
    onValueChange,
    controller,
    debug,
    autoResize,
    onSubmit,
    submitShortcut
  });
  const element = {
    ...elementProps(props, field, value, defaultValue),
    render: controlRender(field, "textarea", render)
  };
  return usePart(
    textarea,
    "root",
    controlProps(props, field),
    element,
    "textarea"
  );
}
export {
  Textarea,
  createInputController
};
